import {defaults} from './avatar.js';
export function convertSourceState(old){const species={cat:'cat',fox:'fox',wolf:'wolf',bear:'bear',mouse:'mouse',hamster:'hamster',dog:'puppy',deer:'deer',deer_antler:'antler',rabbit:'bunny',lop_rabbit:'lop',axolotl:'axolotl',raccoon:'raccoon',otter:'otter',none:'none'};const eyes={angry:'angry',normal:'basic',sad:'down',half:'shy',sparkle:'sparkle',closed:'squint',sleep:'sleepy',smile:'happy',line:'line'};const eyebrows={none:'none',soft:'soft',short_arch:'short',arch:'arch',sharp:'sharp',sad:'sad'};const mouths={line:'flat',cat:'cat',triangle:'pout',smile:'smile',nose_only:'nose',open:'open'};const tails={round:'puff',long:'curl',stub:'stub',fluffy:'fluffy',none:'none'};return{...defaults,name:old.characterName||'친구',species:species[old.earType]??'cat',tail:tails[old.tailType]??'puff',bodyColor:old.bodyColor||defaults.bodyColor,eyeColor:old.oddEye?(old.eyeColorLeft||old.eyeColor):old.eyeColor||defaults.eyeColor,rightEyeColor:old.eyeColorRight||defaults.rightEyeColor,oddEyes:old.oddEye??false,mouthColor:old.noseMouthColor||defaults.mouthColor,bellyColor:old.bellyColor||defaults.bellyColor,bellySeparate:old.bellyPatch??false,patternColor:old.patternColor||defaults.patternColor,facePattern:['none','forehead','cheeks','spots','mask','muzzle','split'].includes(old.patternType)?old.patternType:'none',expression:eyes[old.eyeType]??'sparkle',mouth:mouths[old.mouthType]??'pout',eyelashes:{none:'none',top:'upper',bottom:'lower',both:'both'}[old.eyelashType]??'none',eyebrow:eyebrows[old.eyebrowType]??'none',eyebrowColor:old.eyebrowColor||defaults.eyebrowColor,head:Math.min(1.3,Math.max(.75,(old.headScale??1.08)/1.08)),body:Math.min(1.35,Math.max(.75,(old.bodyChubby??1.18)/1.18)),legs:Math.min(1.45,Math.max(.65,(old.legLength??.7)/.7)),earSeparate:old.earColorCustom??false,earColor:old.earColor||defaults.earColor,armSeparate:old.armColorCustom??false,armColor:old.armColor||defaults.armColor,blush:old.blushType!=='none',halo:false,horns:false,outline:old.outlineEnabled??false,outlineColor:old.outlineColor||defaults.outlineColor,detail:old.polyDetail==='very_low'?'verylow':old.polyDetail==='medium'?'high':'low'};}
